/* ScrollTrigger 3.12.5 Lightweight Engine */
(function(global) {
  'use strict';

  function initTrigger(config) {
    if (!config) return;
    var triggerEl = typeof config.trigger === 'string' ? document.querySelector(config.trigger) : config.trigger;
    if (!triggerEl) return;

    var observer = new IntersectionObserver(function(entries) {
      entries.forEach(function(entry) {
        if (entry.isIntersecting) {
          if (config.onEnter) config.onEnter();
          if (config.animation) {
            if (config.animation.play) config.animation.play();
          }
          if (config.once !== false) observer.unobserve(entry.target);
        }
      });
    }, {
      threshold: config.threshold || 0.05
    });

    observer.observe(triggerEl);
  }

  var ScrollTrigger = {
    create: function(config) {
      initTrigger(config);
      return { kill: function() {} };
    },
    batch: function(targets, config) {
      var els = typeof targets === 'string' ? document.querySelectorAll(targets) : targets;
      Array.from(els).forEach(function(el) {
        initTrigger(Object.assign({}, config, { trigger: el }));
      });
    },
    refresh: function() {},
    config: function() {}
  };

  if (global.gsap) {
    global.gsap.registerPlugin(ScrollTrigger);
  }

  global.ScrollTrigger = ScrollTrigger;
})(typeof window !== 'undefined' ? window : this);
